import json

with open('/tmp/demo.json', 'r') as f:
    data = json.load(f)

test_input = data['test_input']
test_height = len(test_input)
test_width = len(test_input[0])

print(f"Test input dimensions: {test_height}x{test_width}")

# Convert to integers
test_grid = [[int(x) for x in row] for row in test_input]

# Find pairs and singles
rows_with_pairs = []
for r in range(test_height):
    cols = set()
    for c in range(test_width):
        val = test_grid[r][c]
        # Find unique value (excluding background 4)
        for v in [2, 5, 8, 9]:
            if val == v:
                cols.add(v)

    if len(cols) >= 2:
        rows_with_pairs.append((r, list(cols)))

print(f"\nRows with multiple non-4 values:")
for r, vals in rows_with_pairs:
    print(f"  Row {r}: {vals}")

# Apply the rule - find first cluster with horizontal pair and check if below row has single
def predict_output(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Copy

    # Find first row with pair (two different non-4 values adjacent)
    for r in range(h):
        for c in range(w - 2):
            p1, p2 = result[r][c], result[r][c+1]
            if p1 != 4 and p2 != 4 and p1 != p2:
                # Found a pair at (r, c) and (r, c+1)
                # Look for single below: could be at (r+1, c) or (r+1, c+1) or (r+1, c+2)
                found_single = False
                for sc in [c, c+1, c+2]:
                    if sc < w:
                        s = result[r+1][sc]
                        if s != 4 and s != p1 and s != p2:
                            # Found single at (r+1, sc)
                            found_single = True

                            # Add horizontal extension at row r+1
                            for ec in range(c+1, c+4):
                                if ec < w and result[r+1][ec] == 4:
                                    result[r+1][ec] = s

                            # Add vertical line starting from r+2
                            for lr in range(r+2, h):
                                if result[lr][sc] == 4:
                                    result[lr][sc] = 8
                            break
                if found_single:
                    break

    return result

output = predict_output(test_grid)

print("\nPredicted output grid:")
for row in output:
    print(" ".join(str(x) for x in row))

print("\nJSON output:")
print(json.dumps(output))

