            # Look for single below
            for sc in [c, c+2]:
                if sc < len(demo_gin[r]):
                    s = demo_gin[r+1][sc]
                    if s != 7 and s != p1 and s != p2:
                        print(f"Single at ({r+1}, {sc})={s}")
