from copy import deepcopy
def predict_demos(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w - 2):
            p1, p2 = result[r][c], result[r][c+1]
            if p1 != 7 and p2 != 7 and p1 != p2:
                for sc in [c, c+2]:
                    if sc < w and r+1 < h:
                        s = result[r+1][sc]
