                if sc in [c, c+2] and r+1 < h and demo_gin[r+1][sc] != 7 and demo_gin[r+1][sc] != p1 and demo_gin[r+1][sc] != p2:
                    break

    return result

demo_pred = predict_demos(demo_gin)

# Compare
