            if demo_pred[r][c] != demo_gout[r][c]:
                print(f"Mismatch at ({r},{c}): pred={demo_pred[r][c]}, expected={demo_gout[r][c]}")
                match = False

    print("\nDemo prediction grid:")
    for row in demo_pred:
