def get_diag_constants(values_list):
    """Return dict: value -> {'main': const, 'anti': const} for diagonal groups"""
    by_value = defaultdict(list)
    for r, c, v in values_list:
        by_value[v].append((r, c))

    result = {}
    for val, pos in by_value.items():
        # Check if all positions are on same main diagonal
        main_consts = set(c - r for r, c in pos)
        # Check if all positions are on same anti diagonal
        anti_consts = set(c + r for r, c in pos)

        if len(main_consts) == 1 and len(anti_consts) > 1:
            result[val] = {'type': 'main', 'const': list(main_consts)[0]}
        elif len(anti_consts) == 1 and len(main_consts) > 1:
            result[val] = {'type': 'anti', 'const': list(anti_consts)[0]}
