# Generate output using "extend until obstacle" rule
output = [[bg]*len(demo5_input[0]) for _ in range(len(demo5_input))]

def extend_diagonal(output, start_pos, const_type, const_val, steps=None):
    """Extend along diagonal, stopping at obstacles"""
    r, c = start_pos

    # Determine direction based on constant type
    if const_type == 'main':  # c-r = const → move with dr=dc
        # Forward: dr > 0, dc > 0 (down-right)
        for s in range(steps or len(output)):
            nr, nc = r + s, c + s
            if 0 <= nr < len(output) and 0 <= nc < len(output[nr]):
                if output[nr][nc] == bg:
                    output[nr][nc] = start_pos[2]  # Preserve value
                else:
                    break  # Stop at obstacle
            else:
                break
        # Backward: dr < 0, dc < 0 (up-left)
        for s in range(1, steps or len(output)+1):
            nr, nc = r - s, c - s
            if 0 <= nr < len(output) and 0 <= nc < len(output[nr]):
                if output[nr][nc] == bg:
                    output[nr][nc] = start_pos[2]
                else:
                    break
            else:
                break

    elif const_type == 'anti':  # c+r = const → move with dr=-dc
        # Forward: dr > 0, dc < 0 (down-left)
        for s in range(steps or len(output)):
