def find_connected_components(grid, bg_val):
    components = {}
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != bg_val and (r,c) not in visited:
                val = grid[r][c]
                component = []
                queue = deque([(r,c)])
                visited.add((r,c))

                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))

                    # Check all 8 neighbors
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                                if grid[nr][nc] == val and (nr,nc) not in visited:
                                    visited.add((nr,nc))
                                    queue.append((nr,nc))

                if val not in components:
                    components[val] = []
                components[val].append(component)

    return components

