    elif diag_type == 'anti':  # c + r = constant => c = constant - r
        r, c = start_r, constant - start_c

        while True:
            if 0 <= r < len(grid) and 0 <= c < len(grid[r]):
                cell_val = grid[r][c]
                if cell_val == bg or cell_val == value:
                    cells.append((r, c))
                    r += 1
                    c -= 1  # Anti-diag: as r goes up, c goes down
