from collections import deque

def get_diag_through_point(grid, r, c):
    """Get all points on the two diagonals passing through (r,c)"""
    result = []

    # Main diagonal (c - r = constant)
    const_main = c - r
    rr = r
    while True:
        cc = const_main + rr
        if 0 <= rr < len(grid) and 0 <= cc < len(grid[rr]):
            result.append((rr, cc))
            rr += 1
        else:
            break

    rr = r
    while rr >= 0:
        cc = const_main + rr
        if 0 <= rr < len(grid) and 0 <= cc < len(grid[rr]):
            result.append((rr, cc))
            rr -= 1
        else:
            break

    # Anti diagonal (c + r = constant)
    const_anti = c + r
    rr = r
    while True:
        cc = const_anti - rr
        if 0 <= rr < len(grid) and 0 <= cc < len(grid[rr]):
            result.append((rr, cc))
            rr += 1
        else:
            break

    rr = r
    while rr >= 0:
        cc = const_anti - rr
        if 0 <= rr < len(grid) and 0 <= cc < len(grid[rr]):
            result.append((rr, cc))
            rr -= 1
        else:
            break

    return set(result)

