# Process connected pairs
output_grid = [[bg]*cols_in for _ in range(rows_in)]

components = {
    ('main', 9): {'cells': [(15, 11), (16, 10)], 'value': 9},   # Anti-diag pair
    ('anti', 2): {'cells': [(15, 12), (16, 13)], 'value': 2}     # Main-diag pair
}

for diag_type, value in components.keys():
    info = components[(diag_type, value)]
    cells = info['cells']

    if len(cells) == 2:
        (r1, c1), (r2, c2) = cells

        # Verify diagonal type matches
        diff_r = r2 - r1
        diff_c = c2 - c1

        if diag_type == 'main' and diff_r == diff_c:
            const = c1 - r1
        elif diag_type == 'anti' and diff_r + diff_c == 0:
            const = c1 + r1
        else:
            print(f"Error: Diagonal type mismatch!")
            continue

        # Extend from both endpoints
        merged = set()
        for rstart, cstart in cells:
            ext = extend_from_cell(rstart, cstart, diag_type, const, test_input, bg, value)
            merged.update(ext)

        for cell in merged:
            output_grid[cell[0]][cell[1]] = value

# Add isolated cells back
isolated = {(14, 11): 5, (14, 12): 8}
for cell, val in isolated.items():
    output_grid[cell[0]][cell[1]] = val

print("=== Final Output Grid ===")
for r in range(rows_in):
    vals = [str(x) for x in output_grid[r][:15]]
    print(f"Row {r}: {' '.join(vals)}")
